    await check('opetus')
    want('ohje i-napin takana', not await pg.is_visible('#info') and await pg.is_visible('#hint')); await pg.click('#hint'); want('ohje aukeaa', 'Säännöt' in await pg.inner_text('#hs-body') and await pg.inner_text('#hs-h')=='Rakentaminen'); await check('ohje'); await pg.click('#hs-close')
    want('ei jämäohjeita näkymässä', await pg.locator('#p-teach .sub').count()==0)
    await tap('kissa'); await tap('kissa'); await tap('kissa'); y0=(await pg.locator('#tlist').bounding_box())['y']
    want('ehtovalinta työkalurivillä', await pg.is_visible('#tbar #needmode')); await tap('kissa'); want('lista ei pompannut', abs((await pg.locator('#tlist').bounding_box())['y']-y0)<1)
    await pg.evaluate("document.getElementById('main').scrollTop=400"); await pg.wait_for_timeout(30); want('työkalurivi ylhäällä', (await pg.locator('#tbar').bounding_box())['y']<120 or await pg.evaluate("(function(m){return m.scrollHeight<=m.clientHeight+1})(document.getElementById('main'))")); await pg.evaluate("document.getElementById('main').scrollTop=0")
    await pg.click('[data-tm="mx"]'); await pg.click('#mxnew'); await pg.click('#p-teach [data-id="ruoka"]'); await pg.click('#p-teach [data-id="leikki"]'); await pg.click('#mxsave'); await check('toisensa poissulkevat')
    await pg.click('[data-tm="ord"]'); await pg.wait_for_timeout(50); await tap('ruoka'); await tap('leikki'); await tap('ruoka'); await tap('leikki'); await tap('ruoka')
    want('kehä hylätty', 'Ei käy' in await pg.inner_text('#info') and json.loads(await pg.evaluate("JSON.stringify(JSON.parse(localStorage.getItem('paatospuu:v1')).kokonaisuudet[0].puut[0].order)"))=={'ruoka':['leikki']}); await check('järjestys')
    await tap('leikki')
    want('järjestyksessä kaikki palikat', await pg.locator('#tlist .drow').count()==7)
    await pg.click('[data-star="eläimet"]'); await pg.wait_for_timeout(50); await pg.click('[data-star="ruoka"]'); await pg.wait_for_timeout(50)
    want('tähti nostaa', await pg.locator('#ordimp .drow').count()==2 and await pg.locator('#tlist .drow').count()==5)
    bb=await pg.locator('#ordimp .drow').nth(1).bounding_box(); x=bb['x']+bb['width']/3; y=bb['y']+bb['height']/2
    await pg.mouse.move(x,y); await pg.mouse.down(); await pg.wait_for_timeout(450)
    for k in range(1,11): await pg.mouse.move(x,y-9*k)
